<script setup>import {useForm} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; const props=defineProps({product:Object,editing:Boolean,endpoints:Object}); const all=['delinquency','fees','interest','principal']; const form=useForm({code:props.product.code||'',name:props.product.name||'',currency:props.product.currency||'NIO',allowed_frequencies:props.product.allowed_frequencies||['weekly','biweekly','monthly'],allowed_interest_methods:props.product.allowed_interest_methods||['flat','declining_balance','french'],default_interest_rate:props.product.default_interest_rate||'',default_interest_method:props.product.default_interest_method||'',default_administrative_fee:props.product.default_administrative_fee||0,delinquency_method:props.product.delinquency_method||'',delinquency_rate:props.product.delinquency_rate||'',payment_allocation_order:props.product.payment_allocation_order||[...all],minimum_term:props.product.minimum_term||4,maximum_term:props.product.maximum_term||60,is_active:props.product.is_active??true}); const submit=()=>form.transform(d=>props.editing?{...d,_method:'put'}:d).post(props.endpoints.save);</script>
<template><AppLayout :title="editing?'Editar producto':'Nuevo producto'" eyebrow="Configuración financiera" description="Las tasas, mora y prioridad se guardan como configuración; no se incorporan reglas implícitas."><template #header-actions><a :href="endpoints.index" class="btn-secondary">Volver</a></template><form class="space-y-4" @submit.prevent="submit"><section class="card p-5"><h2 class="font-semibold">Identidad y disponibilidad</h2><div class="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="field-label">Código *<input v-model="form.code" class="control" required></label><label class="field-label md:col-span-2">Nombre *<input v-model="form.name" class="control" required></label><label class="field-label">Moneda<select v-model="form.currency" class="control"><option>NIO</option><option>USD</option></select></label><label class="field-label">Plazo mínimo<input v-model="form.minimum_term" type="number" min="1" class="control"></label><label class="field-label">Plazo máximo<input v-model="form.maximum_term" type="number" min="1" class="control"></label><label class="flex items-center gap-2 text-xs"><input v-model="form.is_active" type="checkbox"> Producto activo</label></div></section><section class="card p-5"><h2 class="font-semibold">Interés y frecuencias</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><fieldset><legend class="field-label">Frecuencias permitidas</legend><label v-for="(label,key) in {daily:'Diaria',weekly:'Semanal',biweekly:'Quincenal',monthly:'Mensual'}" :key="key" class="mr-4 mt-3 inline-flex gap-2 text-xs"><input v-model="form.allowed_frequencies" type="checkbox" :value="key">{{label}}</label></fieldset><fieldset><legend class="field-label">Métodos permitidos</legend><label v-for="(label,key) in {flat:'Plano',declining_balance:'Saldo decreciente',french:'Cuota nivelada'}" :key="key" class="mr-4 mt-3 inline-flex gap-2 text-xs"><input v-model="form.allowed_interest_methods" type="checkbox" :value="key">{{label}}</label></fieldset><label class="field-label">Tasa predeterminada<input v-model="form.default_interest_rate" type="number" min="0" step=".000001" class="control"></label><label class="field-label">Método predeterminado<select v-model="form.default_interest_method" class="control"><option value="">Sin definir</option><option value="flat">Plano</option><option value="declining_balance">Saldo decreciente</option><option value="french">Cuota nivelada</option></select></label><label class="field-label">Gasto administrativo<input v-model="form.default_administrative_fee" type="number" min="0" step=".01" class="control"></label></div></section><section class="card p-5"><h2 class="font-semibold">Mora y aplicación de pagos</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><label class="field-label">Método de mora<select v-model="form.delinquency_method" class="control"><option value="">Sin configurar</option><option value="none">Sin mora</option><option value="daily_percentage">Porcentaje diario</option><option value="fixed">Monto fijo</option></select></label><label class="field-label">Tasa o monto<input v-model="form.delinquency_rate" type="number" min="0" step=".000001" class="control"></label></div><div class="mt-4 grid gap-3 sm:grid-cols-4"><label v-for="(_,i) in form.payment_allocation_order" :key="i" class="field-label">{{i+1}}° prioridad<select v-model="form.payment_allocation_order[i]" class="control"><option v-for="value in all" :key="value" :value="value">{{value}}</option></select></label></div></section><div v-if="Object.keys(form.errors).length" class="text-xs text-rose-600">{{Object.values(form.errors).join(' · ')}}</div><button class="btn-primary" :disabled="form.processing">Guardar producto</button></form></AppLayout></template>
